								}
								create_ship = {
									name = "NAME_Life_Tree_Protector"
									design = "NAME_Large_Space_Organism_Orange"
								}
								create_ship = {
									name = "NAME_Life_Tree_Protector"
									design = "NAME_Large_Space_Organism_Orange"
								}
								set_location = event_target:MonsterLocation
								set_fleet_stance = aggressive
