											found_planet = {
												move_to = this
												orbit_planet = THIS
												wait = {
													duration = 50
													random = 20
												}
											}
										}
										find_closest_planet = {
											trigger = {
												id = "life_tree_protector.trigger.2"
												is_same_value = event_target:MonsterLocation
											}
											found_planet = {
												move_to = this
											}
										}
									}
								}
							}
						}
					}
				}
			}
		}
	}

